SELECT 
FROM ai_agent_featured_conversation

    deleted = 0

        AND status = #{status}


        AND session_id = #{sessionId}


        AND title LIKE CONCAT('%', #{title}, '%')


ORDER BY sort_order DESC, id DESC
LIMIT #{offset}, #{limit}

